"use strict";
const STORAGE = 'serenazgo-miraflores-demo-v1';
const starter = [
    { id: 'MIR-2026-0842', type: 'Actividad sospechosa', location: 'Av. Progreso, Miraflores', date: 'Hoy, 18:42', status: 'En camino', note: 'Unidad S-04 asignada al incidente', priority: 'Alta' },
    { id: 'MIR-2026-0839', type: 'Ruido y alteración del orden', location: 'Calle Puno, Miraflores', date: 'Hoy, 17:26', status: 'Atendida', note: 'Incidente atendido por serenazgo', priority: 'Media' },
    { id: 'MIR-2026-0834', type: 'Alumbrado público', location: 'Parque Mayta Cápac', date: 'Ayer, 21:10', status: 'Atendida', note: 'Derivado al área correspondiente', priority: 'Baja' }
];
let incidents = readIncidents();
let page = 'inicio';
let countdown = null;
let countdownTimer = null;
let selectedIncident = incidents[0]?.id ?? '';
let toastTimer = null;
let rating = 0;
const $ = (selector) => document.querySelector(selector);
function readIncidents() { try {
    const x = localStorage.getItem(STORAGE);
    return x ? JSON.parse(x) : starter;
}
catch {
    return starter;
} }
function save() { localStorage.setItem(STORAGE, JSON.stringify(incidents)); }
function escapeHtml(value) { return value.replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c] ?? c)); }
function notify(msg) { const toast = $('#toast'); toast.textContent = msg; toast.classList.add('show'); if (toastTimer)
    clearTimeout(toastTimer); toastTimer = window.setTimeout(() => toast.classList.remove('show'), 3500); }
function statusBadge(status) { const classes = { 'Recibida': 'received', 'En camino': 'progress', 'Atendida': 'done' }; return `<span class="pill ${classes[status]}"><span class="pill-dot"></span>${status}</span>`; }
function headerFor(p) { return { inicio: ['Panel ciudadano', 'Seguridad cerca de ti, información en cada paso.'], reportes: ['Mis reportes', 'Consulta cada etapa de la atención de tus incidencias.'], cobertura: ['Mapa de cobertura', 'Conoce las zonas y unidades simuladas del distrito.'], comunidad: ['Alertas comunitarias', 'Avisos preventivos para mantenerte informado.'], valoracion: ['Califica la atención', 'Tu opinión ayuda a mejorar el servicio.'] }[p]; }
function icon(name, size = 20) { const paths = { home: '<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>', report: '<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>', map: '<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15M15 6v15"/>', bell: '<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>', star: '<path d="m12 2 3.1 6.3 7 .9-5.1 5 .9 7-5.9-3.2-5.9 3.2.9-7-5.1-5 7-.9z"/>', shield: '<path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11z"/><path d="m9 12 2 2 4-4"/>', arrow: '<path d="M5 12h14m-6-6 6 6-6 6"/>', pin: '<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0z"/><circle cx="12" cy="10" r="2"/>', clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', check: '<path d="m5 12 5 5L20 7"/>', phone: '<path d="M22 16.92v3a2 2 0 0 1-2.18 2A19.8 19.8 0 0 1 2.09 4.18 2 2 0 0 1 4.08 2h3a2 2 0 0 1 2 1.72l.45 2.8a2 2 0 0 1-.57 1.7l-1.3 1.3a16 16 0 0 0 6.8 6.8l1.3-1.3a2 2 0 0 1 1.7-.57l2.8.45A2 2 0 0 1 22 16.92z"/>', alert: '<path d="m12 3 10 18H2L12 3z"/><path d="M12 9v4M12 17h.01"/>', close: '<path d="M5 5l14 14M19 5 5 19"/>', chevron: '<path d="m9 18 6-6-6-6"/>', calendar: '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>', users: '<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M17 11a3 3 0 0 0 0-6M18 20h3v-2a6 6 0 0 0-4-5.65"/>', send: '<path d="m22 2-7 20-4-9-9-4zM22 2 11 13"/>', info: '<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>' }; return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round" fill="none" aria-hidden="true">${paths[name] || paths.info}</svg>`; }
function reportCard(i) { return `<button class="report-row" data-view="${escapeHtml(i.id)}"><span class="incident-glyph">${icon('shield', 19)}</span><span class="incident-main"><strong>${escapeHtml(i.type)}</strong><small>${icon('pin', 13)} ${escapeHtml(i.location)} · ${escapeHtml(i.date)}</small></span>${statusBadge(i.status)}<span class="chevron">${icon('chevron', 18)}</span></button>`; }
function tracking(i) { const steps = ['Recibida', 'En camino', 'Atendida']; const level = steps.indexOf(i.status); return `<div class="tracking-head"><span class="mini-eyebrow">SEGUIMIENTO DEL REPORTE</span><span class="case-id">#${escapeHtml(i.id)}</span></div><div class="tracking-title">${escapeHtml(i.type)}</div><p class="tracking-location">${icon('pin', 15)} ${escapeHtml(i.location)}</p><div class="steps">${steps.map((s, j) => `<div class="step ${j <= level ? 'active' : ''}"><span class="step-dot">${j < level ? icon('check', 13) : j + 1}</span><span class="step-copy"><strong>${s}</strong><small>${['Tu reporte fue registrado', 'Una unidad fue asignada', 'La unidad completó la atención'][j]}</small></span></div>`).join('')}</div><div class="tracking-note">${icon('info', 16)} ${escapeHtml(i.note)}</div><div class="sim-actions"><button class="text-button" data-advance="${escapeHtml(i.id)}" ${i.status === 'Atendida' ? 'disabled' : ''}>${i.status === 'Atendida' ? 'Atención completada' : 'Simular siguiente estado'} ${icon('arrow', 15)}</button></div>`; }
function mapMarkup() { return `<div class="map-wrap"><div class="street-map"><svg class="city-grid" viewBox="0 0 850 430" preserveAspectRatio="xMidYMid slice"><rect width="850" height="430" fill="#eef4ee"/><path d="M0 40 850 360M0 120 850 440M0 225 630 0M0 355 850 45M130 430 850 165" stroke="#fff" stroke-width="26"/><path d="M0 40 850 360M0 120 850 440M0 225 630 0M0 355 850 45M130 430 850 165" stroke="#cdd9d2" stroke-width="1"/><path d="M140 0 250 430M380 0 490 430M600 0 710 430M830 0 850 80" stroke="#fff" stroke-width="17"/><path d="M140 0 250 430M380 0 490 430M600 0 710 430M830 0 850 80" stroke="#d8e2dc" stroke-width="1"/><path d="M0 300 185 390 310 320 145 215z" fill="#cae7cd" opacity=".8"/><path d="M540 30 715 105 615 185 455 130z" fill="#cce7ce" opacity=".85"/><g fill="#7f948d" font-family="Arial" font-size="13" font-weight="600"><text x="300" y="90" transform="rotate(19 300 90)">Av. Progreso</text><text x="510" y="310" transform="rotate(-21 510 310)">Av. Goyeneche</text><text x="95" y="280" transform="rotate(16 95 280)">Calle Puno</text><text x="540" y="90">Parque local</text><text x="330" y="405">MIRAFLORES · AREQUIPA</text></g></svg><span class="map-marker m1"><span>🚓</span><small>S-04</small></span><span class="map-marker m2"><span>🚓</span><small>S-12</small></span><span class="map-marker m3"><span>🚓</span><small>S-07</small></span><span class="map-marker home-pin">${icon('pin', 19)}</span><span class="map-caption">${icon('info', 14)} Mapa ilustrativo · Posiciones simuladas</span></div></div>`; }
function sidebar() { return `<aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('shield', 27)}</span><span><strong>SERENAZGO</strong><small>CONECTADO</small></span></div><div class="brand-district">MIRAFLORES · AREQUIPA</div><div class="sidebar-section-label">MENÚ PRINCIPAL</div><nav>${[['inicio', 'home', 'Inicio'], ['reportes', 'report', 'Mis reportes'], ['cobertura', 'map', 'Mapa de cobertura'], ['comunidad', 'bell', 'Alertas comunitarias'], ['valoracion', 'star', 'Calificar atención']].map(([id, ic, name]) => `<button class="nav-item ${page === id ? 'selected' : ''}" data-page="${id}">${icon(ic, 20)} <span>${name}</span>${id === 'comunidad' ? '<span class="nav-count">3</span>' : ''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="help-card"><span class="help-icon">${icon('phone', 19)}</span><strong>¿Necesitas ayuda?</strong><p>Ante una emergencia real, contacta los canales oficiales de tu localidad.</p><button id="help-info">Ver información ${icon('arrow', 14)}</button></div><div class="sidebar-footer">Prototipo académico · No operativo</div></div></aside>`; }
function home() { return `<div class="hero"><div class="hero-left"><span class="hero-tag">${icon('shield', 14)} TU SEGURIDAD ES NUESTRA PRIORIDAD</span><h2>Tu tranquilidad,<br><em>más cerca que nunca.</em></h2><p>Reporta una situación, sigue su atención y mantente informado desde un solo lugar.</p><button class="light-outline" data-page="reportes">Ver mis reportes ${icon('arrow', 17)}</button></div><div class="hero-illustration"><div class="hero-circle c1"></div><div class="hero-circle c2"></div><div class="hero-shield">${icon('shield', 84)}</div><div class="hero-mini m-a">${icon('check', 15)} Reporte recibido</div><div class="hero-mini m-b">${icon('pin', 15)} Unidad cercana</div></div></div><div class="stats"><div class="stat"><div class="stat-icon blue">${icon('report', 20)}</div><div><small>Mis reportes</small><strong>${incidents.length}</strong><span>Registrados en demo</span></div></div><div class="stat"><div class="stat-icon orange">${icon('clock', 20)}</div><div><small>En proceso</small><strong>${incidents.filter(i => i.status !== 'Atendida').length}</strong><span>Pendientes de atención</span></div></div><div class="stat"><div class="stat-icon green">${icon('check', 20)}</div><div><small>Atendidos</small><strong>${incidents.filter(i => i.status === 'Atendida').length}</strong><span>Incidencias finalizadas</span></div></div></div><div class="dashboard-grid"><div class="main-column"><section class="panel emergency-panel"><div class="panel-head"><div><span class="mini-eyebrow">ACCESO RÁPIDO</span><h3>¿Necesitas reportar algo?</h3><p>Utiliza este acceso para crear una alerta de demostración.</p></div><span class="red-alert-icon">${icon('alert', 22)}</span></div><button id="panic-btn" class="panic-button"><span class="panic-pulse">${icon('alert', 29)}</span><span><strong>ENVIAR ALERTA</strong><small>Emergencia simulada</small></span>${icon('arrow', 20)}</button><div class="emergency-foot">${icon('info', 15)} Se aplicará una cuenta regresiva de 3 segundos para evitar alertas accidentales.</div></section><section class="panel"><div class="panel-head compact"><div><h3>Actividad reciente</h3><p>Últimos reportes registrados</p></div><button class="text-button" data-page="reportes">Ver todos ${icon('arrow', 15)}</button></div><div class="report-list">${incidents.slice(0, 3).map(reportCard).join('')}</div></section></div><div class="side-column"><section class="panel tracking-panel">${tracking(incidents.find(i => i.id === selectedIncident) ?? incidents[0])}</section><section class="panel community-small"><div class="panel-head compact"><div><h3>Alerta en tu zona</h3><p>Información preventiva</p></div><span class="alert-pill">RECIENTE</span></div><div class="bullet-alert"><span>${icon('bell', 20)}</span><div><strong>Precaución en vías concurridas</strong><p>Mantente atento a tu entorno y reporta actividades sospechosas.</p></div></div><button class="text-button" data-page="comunidad">Ver alertas comunitarias ${icon('arrow', 15)}</button></section></div></div>`; }
function reports() { return `<div class="page-heading"><div><h2>Historial de reportes</h2><p>Consulta el estado de cada incidencia y su evolución.</p></div><button class="primary-btn" id="new-report">${icon('alert', 17)} Nuevo reporte</button></div><div class="reports-layout"><section class="panel reports-panel"><div class="panel-head compact"><h3>Mis incidencias <span class="count-chip">${incidents.length}</span></h3><span class="muted-tag">Datos demostrativos</span></div><div class="report-list tall">${incidents.map(reportCard).join('')}</div></section><section class="panel tracking-panel">${tracking(incidents.find(i => i.id === selectedIncident) ?? incidents[0])}</section></div>`; }
function coverage() { return `<div class="page-heading"><div><h2>Cobertura de serenazgo</h2><p>Visualiza un escenario ilustrativo de patrullaje por sectores.</p></div><span class="demo-label">${icon('info', 15)} Simulación</span></div><div class="coverage-layout"><section class="panel map-panel"><div class="panel-head compact"><div><h3>Unidades en el distrito</h3><p>Miraflores, Arequipa · mapa de referencia</p></div><span class="online-marker"><span></span> 3 unidades simuladas</span></div>${mapMarkup()}</section><section class="panel units-panel"><h3>Unidades de demostración</h3><p class="muted">Su ubicación no corresponde a patrulleros reales.</p>${[['S-04', 'Sector centro', 'En recorrido'], ['S-12', 'Sector norte', 'Disponible'], ['S-07', 'Sector sur', 'En recorrido']].map(([code, zone, st]) => `<div class="unit-row"><span class="unit-icon">${icon('shield', 19)}</span><div><strong>Unidad ${code}</strong><small>${zone}</small></div><span class="unit-status">${st}</span></div>`).join('')}<div class="legend"><span><i class="legend-dot green"></i> Unidad simulada</span><span><i class="legend-dot blue"></i> Ubicación ilustrativa</span></div></section></div>`; }
function community() { const alerts = [{ title: 'Precaución en zonas de alta afluencia', date: 'Hoy · 18:30', body: 'Evita dejar pertenencias sin vigilancia y mantente atento a tu entorno.', type: 'Prevención', icon: 'bell' }, { title: 'Recomendaciones de seguridad nocturna', date: 'Hoy · 16:15', body: 'Prefiere vías iluminadas y comunica situaciones de riesgo por canales oficiales.', type: 'Consejo', icon: 'shield' }, { title: 'Campaña de participación vecinal', date: 'Ayer · 12:20', body: 'La colaboración entre vecinos contribuye a identificar y prevenir incidentes.', type: 'Comunidad', icon: 'users' }]; return `<div class="page-heading"><div><h2>Alertas y avisos</h2><p>Información preventiva para fortalecer la seguridad de la comunidad.</p></div><span class="demo-label">Contenido de ejemplo</span></div><div class="community-list">${alerts.map(a => `<article class="panel alert-article"><span class="community-icon">${icon(a.icon, 23)}</span><div><div class="community-meta"><span class="alert-category">${a.type}</span><span>${a.date}</span></div><h3>${a.title}</h3><p>${a.body}</p><div class="community-location">${icon('pin', 14)} Miraflores, Arequipa</div></div></article>`).join('')}</div>`; }
function valuation() { return `<div class="page-heading"><div><h2>Tu experiencia importa</h2><p>Ayúdanos a visualizar cómo sería la evaluación ciudadana.</p></div></div><div class="rating-layout"><section class="panel rating-card"><span class="rating-medallion">${icon('star', 32)}</span><h3>¿Cómo calificarías la atención?</h3><p>Elige de 1 a 5 estrellas y comparte una sugerencia. Este formulario es solamente demostrativo.</p><div class="rating-stars">${[1, 2, 3, 4, 5].map(n => `<button class="rate-star ${n <= rating ? 'filled' : ''}" data-star="${n}" aria-label="Calificar ${n} estrellas">${icon('star', 35)}</button>`).join('')}</div><div class="rating-caption">${rating === 0 ? 'Selecciona una calificación' : (['', 'Muy mala', 'Mala', 'Regular', 'Buena', 'Excelente'][rating])}</div><label for="rating-comment">Comentarios (opcional)</label><textarea id="rating-comment" placeholder="Cuéntanos cómo mejorarías el servicio..." rows="5"></textarea><button id="send-rating" class="primary-btn wide">${icon('send', 17)} Enviar valoración simulada</button></section><aside class="panel rating-explain"><h3>¿Por qué evaluar?</h3><div class="reason">${icon('check', 19)} <span>Identificar oportunidades de mejora</span></div><div class="reason">${icon('check', 19)} <span>Conocer la percepción ciudadana</span></div><div class="reason">${icon('check', 19)} <span>Promover una atención transparente</span></div><div class="feedback-notice">${icon('info', 17)} No se transmiten datos a ninguna entidad pública.</div></aside></div>`; }
function render() { const [title, subtitle] = headerFor(page); document.getElementById('app').innerHTML = `<div class="app-layout">${sidebar()}<main class="main"><header class="topbar"><div><div class="breadcrumb">PLATAFORMA CIUDADANA <span> / </span> ${title.toUpperCase()}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="top-actions"><span class="demo-chip">${icon('info', 15)} MODO DEMOSTRACIÓN</span><span class="avatar">VC</span></div></header><div class="content">${({ inicio: home, reportes: reports, cobertura: coverage, comunidad: community, valoracion: valuation })[page]()}</div><footer class="main-footer"><span>Serenazgo Conectado · Prototipo conceptual</span><span>Miraflores, Arequipa · Sin conexión con servicios reales</span></footer></main></div><div id="toast" role="status" aria-live="polite"></div><div id="modal-root"></div>`; bind(); }
function choosePage(next) { page = next; render(); window.scrollTo(0, 0); }
function bind() { document.querySelectorAll('[data-page]').forEach(el => el.addEventListener('click', () => choosePage(el.dataset.page))); document.querySelectorAll('[data-view]').forEach(el => el.addEventListener('click', () => { selectedIncident = el.dataset.view ?? selectedIncident; page = 'reportes'; render(); })); document.querySelectorAll('[data-advance]').forEach(el => el.addEventListener('click', () => { const i = incidents.find(x => x.id === el.dataset.advance); if (!i)
    return; i.status = i.status === 'Recibida' ? 'En camino' : 'Atendida'; i.note = i.status === 'En camino' ? 'Unidad S-04 asignada al incidente' : 'Atención finalizada (simulación)'; save(); render(); notify(`Reporte ${i.id}: ${i.status}`); })); $('#panic-btn')?.addEventListener('click', startEmergency); $('#new-report')?.addEventListener('click', startEmergency); $('#help-info')?.addEventListener('click', () => notify('Este prototipo no envía emergencias. Comunícate con los servicios oficiales ante una situación real.')); document.querySelectorAll('[data-star]').forEach(el => el.addEventListener('click', () => { rating = Number(el.dataset.star); render(); })); $('#send-rating')?.addEventListener('click', () => { if (!rating) {
    notify('Selecciona una calificación de 1 a 5 estrellas.');
    return;
} const comment = $('#rating-comment').value; rating = 0; render(); notify(`¡Gracias! Valoración simulada registrada${comment ? ' con comentario' : ''}.`); }); }
function startEmergency() { if (countdownTimer)
    return; countdown = 3; showEmergencyModal(); countdownTimer = window.setInterval(() => { countdown--; if (countdown > 0) {
    clearInterval(countdownTimer);
    countdownTimer = null;
    countdown = null;
    createIncident();
    return;
} showEmergencyModal(); }, 1000); }
function showEmergencyModal() { $('#modal-root').innerHTML = `<div class="modal-backdrop" role="dialog" aria-modal="true" aria-label="Confirmar alerta de emergencia"><div class="emergency-modal"><div class="modal-danger-icon">${icon('alert', 31)}</div><span class="mini-eyebrow">ALERTA DE DEMOSTRACIÓN</span><h2>Generando reporte...</h2><p>Tu alerta simulada se registrará en <strong>Miraflores, Arequipa</strong>.</p><div class="countdown-num">${countdown}</div><p class="countdown-hint">Segundos para cancelar</p><button id="cancel-emergency" class="cancel-btn">Cancelar alerta</button><small>No se contactará a serenazgo ni a los servicios de emergencia.</small></div></div>`; $('#cancel-emergency').addEventListener('click', () => { if (countdownTimer)
    clearInterval(countdownTimer); countdownTimer = null; countdown = null; $('#modal-root').innerHTML = ''; notify('Alerta cancelada. No se creó ningún reporte.'); }); }
function createIncident() { const num = String(Math.floor(1000 + Math.random() * 9000)); const date = new Date(); const id = `MIR-2026-${num}`; const i = { id, type: 'Alerta de emergencia', location: 'Miraflores, Arequipa (ubicación simulada)', date: `Hoy, ${date.toLocaleTimeString('es-PE', { hour: '2-digit', minute: '2-digit' })}`, status: 'Recibida', note: 'Reporte creado en el prototipo. No fue enviado a serenazgo.', priority: 'Alta' }; incidents.unshift(i); selectedIncident = id; save(); $('#modal-root').innerHTML = ''; page = 'reportes'; render(); notify(`Reporte de prueba ${id} creado correctamente.`); }
render();
